  assert.equal(payment.ok, true);

  const result = overdueInvoices([payment.value], '2025-02-15');

  assert.equal(result.ok, true);
  // C-001 is gold tier: 9500 - 475 + 1895 = 10920
  // Due is 10920 - 5000 = 5920
  assert.equal(result.value[0].due, 5920);
});

